(() => {
	const f = [];
	function c(t) {
		return htmx.closest(t, "[data-loading-states]") || document.body;
	}
	function u(t, n) {
		if (document.body.contains(t)) {
			n();
		}
	}
	function o(t, n) {
		const a = htmx.closest(t, "[data-loading-path]");
		if (!a) {
			return true;
		}
		return a.getAttribute("data-loading-path") === n;
	}
	function e(t, n, a, o) {
		const i = htmx.closest(t, "[data-loading-delay]");
		if (i) {
			const c = i.getAttribute("data-loading-delay") || 200;
			const e = setTimeout(() => {
				a();
				f.push(() => {
					u(n, o);
				});
			}, c);
			f.push(() => {
				u(n, () => {
					clearTimeout(e);
				});
			});
		} else {
			a();
			f.push(() => {
				u(n, o);
			});
		}
	}
	function s(t, n, a) {
		return Array.from(htmx.findAll(t, "[" + n + "]")).filter((t) => o(t, a));
	}
	function r(t) {
		if (t.getAttribute("data-loading-target")) {
			return Array.from(htmx.findAll(t.getAttribute("data-loading-target")));
		}
		return [t];
	}
	htmx.defineExtension("loading-states", {
		onEvent: (t, n) => {
			if (t === "htmx:beforeRequest") {
				const a = c(n.target);
				const o = [
					"data-loading",
					"data-loading-class",
					"data-loading-class-remove",
					"data-loading-disable",
					"data-loading-aria-busy",
				];
				const i = {};
				o.forEach((t) => {
					i[t] = s(a, t, n.detail.pathInfo.requestPath);
				});
				i["data-loading"].forEach((n) => {
					r(n).forEach((t) => {
						e(
							n,
							t,
							() => {
								t.style.display =
									n.getAttribute("data-loading") || "inline-block";
							},
							() => {
								t.style.display = "none";
							},
						);
					});
				});
				i["data-loading-class"].forEach((t) => {
					const a = t.getAttribute("data-loading-class").split(" ");
					r(t).forEach((n) => {
						e(
							t,
							n,
							() => {
								a.forEach((t) => {
									n.classList.add(t);
								});
							},
							() => {
								a.forEach((t) => {
									n.classList.remove(t);
								});
							},
						);
					});
				});
				i["data-loading-class-remove"].forEach((t) => {
					const a = t.getAttribute("data-loading-class-remove").split(" ");
					r(t).forEach((n) => {
						e(
							t,
							n,
							() => {
								a.forEach((t) => {
									n.classList.remove(t);
								});
							},
							() => {
								a.forEach((t) => {
									n.classList.add(t);
								});
							},
						);
					});
				});
				i["data-loading-disable"].forEach((n) => {
					r(n).forEach((t) => {
						e(
							n,
							t,
							() => {
								t.disabled = true;
							},
							() => {
								t.disabled = false;
							},
						);
					});
				});
				i["data-loading-aria-busy"].forEach((n) => {
					r(n).forEach((t) => {
						e(
							n,
							t,
							() => {
								t.setAttribute("aria-busy", "true");
							},
							() => {
								t.removeAttribute("aria-busy");
							},
						);
					});
				});
			}
			if (t === "htmx:beforeOnLoad") {
				while (f.length > 0) {
					f.shift()();
				}
			}
		},
	});
})();
